# Call interviews: phone screening and video interviews. T(hinglish, english) keeps both languages together.
STAGE("s7", "Call interviews", T("Phone aur video interview", "Phone and video interviews"),
      T("Call par kaise bolein, kaise jawab dein aur kya bolein — phone screening se video round tak", "How to talk on a call, how to respond and what to say — from the phone screen to the video round"))

LESSON("c01", "s7", "Before the call: setup and the first 30 seconds", T("Call se pehle ki taiyari aur shuruaat", "Preparing for the call and the opening"), [
    P(T("Zyadatar interviews ab phone ya video par hote hain. Pehle round (recruiter ki **phone screening**) mein aapko 15–30 minute milte hain — isliye **pehle 30 second** ka asar bahut hota hai.",
        "Most interviews now happen by phone or video. In the first round (the recruiter's **phone screen**) you get 15–30 minutes — so the **first 30 seconds** leave a big impression.")),
    H(T("Call se 10 minute pehle", "10 minutes before the call")),
    TBL([T("Kya check karein", "What to check"), T("Kyun", "Why")],
        [T("Shaant jagah, darwaza band", "A quiet place, door closed"), T("Background awaaz se samajhna mushkil hota hai", "Background noise makes you hard to understand")],
        [T("Earphones + mic test", "Earphones + mic test"), T("Awaaz saaf jaati hai, echo nahi", "Your voice is clear, with no echo")],
        [T("Internet / phone ki battery", "Internet / phone battery"), T("Beech mein call na kate", "So the call does not drop midway")],
        [T("Resume, job description, paani", "Resume, job description, water"), T("Sawaal ka jawab dete waqt yaad rahega", "Helps you remember things while answering")],
        [T("Notes ka ek page (bullet points)", "One page of notes (bullet points)"), T("Padhna nahi — bas yaad dilane ke liye", "Not to read from — just to jog your memory")]),
    H(T("Call utha kar shuruaat", "Answering the call")),
    P(T("Phone par **pehle aap bolte ho**, to confident aur saaf bolo. Ek chhota sa script rakho:", "On a phone call **you speak first**, so speak confidently and clearly. Keep a short script:")),
    EX("Hello, this is Rahul speaking. | हेलो, मैं राहुल बोल रहा हूँ।",
       "Hi, thank you for calling. Yes, this is a good time to talk. | नमस्ते, कॉल करने के लिए धन्यवाद। हाँ, अभी बात करने का अच्छा समय है।",
       "Good morning, I can hear you clearly. | नमस्ते, आप मुझे साफ़ सुनाई दे रहे हैं।",
       "Thank you for taking the time to speak with me today. | आज मुझसे बात करने के लिए समय निकालने के लिए धन्यवाद।"),
    TIP(T("Agar recruiter poochhe 'Is this a good time?' aur aap busy ho, to seedha bolo: 'Could we schedule it for later today? I would like to give you my full attention.' Ye professional lagta hai.",
          "If the recruiter asks 'Is this a good time?' and you are busy, say it plainly: 'Could we schedule it for later today? I would like to give you my full attention.' This sounds professional.")),
    H(T("Video call mein extra", "Extra for video calls")),
    P(T("Camera aankh ki level par rakho, roshni aapke **saamne** ho (peeche nahi), aur jawab dete waqt **camera ki taraf** dekho, screen ki taraf nahi. Shuru mein muskurao aur 'Hello' bolo.",
        "Keep the camera at eye level, with the light **in front of** you (not behind), and look **at the camera** while answering, not at the screen. Smile and say 'Hello' at the start.")),
], [
    Q(T("Phone call par pehle kaun bolta hai?", "On a phone call, who speaks first?"), ["The recruiter always speaks first.", "You do, so be ready with a greeting.", "Nobody; wait silently.", "The one who is older."], 1, T("Call utha kar pehle aap bolte ho: 'Hello, this is ... speaking.'", "You answer first: 'Hello, this is ... speaking.'")),
    Q(T("Notes ka sahi use?", "How should you use notes?"), ["Read every answer word for word.", "Keep bullet points to jog your memory.", "Do not keep any notes at all.", "Read the resume aloud."], 1, T("Notes yaad dilane ke liye hote hain, padhne ke liye nahi.", "Notes are to remind you, not to read from.")),
    Q(T("Agar abhi baat karna mushkil ho?", "What if you cannot talk right now?"), ["Hang up.", "Say 'Could we schedule it for later today?'", "Talk while walking in traffic.", "Say nothing."], 1, T("Politely naya time maango.", "Politely ask for another time.")),
    Q(T("Video call mein kahan dekhna chahiye?", "Where should you look on a video call?"), ["At your own face on screen.", "At the camera.", "At the ceiling.", "At your notes all the time."], 1, T("Camera ki taraf dekhne se aankh ka sampark (eye contact) banta hai.", "Looking at the camera creates eye contact.")),
    Q(T("Kaun sa shuruaati sentence accha hai?", "Which opening sentence is good?"), ["What?", "Hello, this is Rahul speaking. Thank you for calling.", "Yes tell.", "Who is this?"], 1, T("Naam + dhanyavaad = professional shuruaat.", "Name + thanks = a professional opening.")),
])

LESSON("c02", "s7", "How to talk on a call: pace, pauses and clarity", T("Call par kaise bolein: speed, pause aur saaf awaaz", "How to talk on a call: pace, pauses and clear speech"), [
    P(T("Call par face aur hand ke ishare nahi dikhte — sab kuch **awaaz** se jata hai. Isliye call par thoda **dheere, saaf aur chhote sentences** mein bolna chahiye.",
        "On a call nobody can see your face or hands — everything goes through your **voice**. So speak a little **slower, clearer and in shorter sentences**.")),
    H(T("5 niyam", "5 rules")),
    TBL([T("Niyam", "Rule"), T("Kaise", "How")],
        [T("1. Dheere bolo", "1. Speak slowly"), T("Normal se thoda dheere; call par awaaz compress hoti hai.", "A bit slower than normal; audio gets compressed on calls.")],
        [T("2. Sawaal poora sunne do", "2. Let the question finish"), T("Beech mein mat bolo; 1 second ruk kar jawab shuru karo.", "Do not interrupt; wait 1 second, then start your answer.")],
        [T("3. Chhote sentences", "3. Short sentences"), T("Ek sentence = ek idea. Lambe sentences mein loge to khud kho jaoge.", "One sentence = one idea. Long sentences make you lose your way.")],
        [T("4. Chup rehna theek hai", "4. Silence is fine"), T("Sochne ke liye 2–3 second ka pause lo; 'umm' se behtar hai.", "Take a 2–3 second pause to think; it is better than 'umm'.")],
        [T("5. Beech-beech mein confirm karo", "5. Check in"), T("Lambe jawab ke baad: 'Does that answer your question?'", "After a long answer: 'Does that answer your question?'")]),
    H(T("Samajh na aaye to", "When you did not understand")),
    P(T("Call par sunai na dena ya samajh na aana **normal** hai. Andaaza lagake galat jawab dene se behtar hai ki **poochh lo**. Interviewer isse acchi baat maante hain.",
        "Not hearing or not understanding on a call is **normal**. It is better to **ask** than to guess and answer wrongly. Interviewers see that as a good sign.")),
    EX("Sorry, could you repeat that, please? | माफ़ कीजिए, क्या आप दोहरा सकते हैं?",
       "Could you speak a little slower? | क्या आप थोड़ा धीरे बोल सकते हैं?",
       "Just to confirm, you are asking about my experience with Java, right? | बस पक्का करने के लिए, आप Java के मेरे अनुभव के बारे में पूछ रहे हैं, सही?",
       "Could you rephrase the question, please? | क्या आप सवाल दूसरे तरीके से पूछ सकते हैं?",
       "Let me think about that for a moment. | मुझे इस पर एक पल सोचने दीजिए।"),
    TIP(T("'What?' ya 'Huh?' mat bolo — rude lagta hai. Hamesha 'Sorry, could you repeat that?' bolo.", "Do not say 'What?' or 'Huh?' — it sounds rude. Always say 'Sorry, could you repeat that?'")),
    H(T("Jawab ka resham: Haan, Wajah, Example", "The answer thread: Yes, Reason, Example")),
    P(T("Har jawab ke liye 3 hisse: **Seedha jawab** (1 sentence) → **Wajah** (1 sentence) → **Example** (1–2 sentence). Isse jawab 20–30 second ka hota hai.",
        "Give every answer 3 parts: a **direct answer** (1 sentence) → a **reason** (1 sentence) → an **example** (1–2 sentences). That makes an answer of 20–30 seconds.")),
    EX("Yes, I have worked with Spring Boot. | हाँ, मैंने Spring Boot पर काम किया है।",
       "I used it to build a REST API for my expense tracker. | मैंने इसे अपने expense tracker का REST API बनाने के लिए इस्तेमाल किया।",
       "For example, I added validation and handled error responses. | उदाहरण के लिए, मैंने validation जोड़ा और error responses संभाले।"),
], [
    Q(T("Call par kaise bolna chahiye?", "How should you speak on a call?"), ["Very fast to save time.", "A little slower, clear, short sentences.", "In a whisper.", "With long sentences."], 1, T("Call par awaaz compress hoti hai, isliye dheere aur saaf.", "Audio is compressed on calls, so slow and clear.")),
    Q(T("Sawaal samajh na aaye to?", "If you did not understand the question?"), ["Guess and answer.", "Say 'What?'", "Say 'Sorry, could you repeat that, please?'", "Stay silent."], 2, T("Polite tareeke se dobara poochho.", "Politely ask again.")),
    Q(T("Jawab ke 3 hisse?", "The 3 parts of an answer?"), ["Greeting, joke, goodbye", "Direct answer, reason, example", "Question, question, question", "Name, age, city"], 1, T("Seedha jawab, wajah, example.", "Direct answer, reason, example.")),
    Q(T("Sochne ke liye kya karein?", "What do you do to think?"), ["Say 'Let me think about that for a moment.'", "Hang up.", "Change the topic.", "Say 'I don't care.'"], 0, T("Ye phrase sochne ka time deta hai.", "This phrase buys you thinking time.")),
    Q(T("Lambe jawab ke baad?", "After a long answer?"), ["Say 'Does that answer your question?'", "Say bye.", "Repeat it twice.", "Say nothing."], 0, T("Confirm karna interviewer ko control deta hai.", "Checking in gives the interviewer control.")),
])

LESSON("c03", "s7", "How to respond: common call questions and what to say", T("Kaise jawab dein: aam sawaal aur kya bolein", "How to respond: common call questions and what to say"), [
    P(T("Phone screening mein sawaal lagbhag hamesha wahi hote hain. Har ek ke liye ek **tayyar dhaancha** rakho — shabd badal do, par structure wahi rakho.",
        "Phone screens ask almost the same questions every time. Keep a **ready structure** for each — change the words, keep the structure.")),
    H(T("1. 'Tell me about yourself' (45 second)", "1. 'Tell me about yourself' (45 seconds)")),
    EX("I am a Java developer with a year of project experience. | मैं एक Java developer हूँ जिसके पास एक साल का project अनुभव है।",
       "Recently I built an expense tracker with a REST API and a database. | हाल ही में मैंने REST API और database के साथ एक expense tracker बनाया।",
       "I am now looking for a backend role where I can grow with a strong team. | अब मैं ऐसा backend role ढूँढ रहा हूँ जहाँ मैं अच्छी team के साथ आगे बढ़ सकूँ।"),
    H(T("2. 'Why are you looking for a change?'", "2. 'Why are you looking for a change?'")),
    P(T("Purane company ki **burai mat karo**. Seekhne aur aage badhne par baat karo.", "Never **criticise** your old company. Talk about learning and growth.")),
    EX("I have learned a lot, and now I want to take on bigger responsibilities. | मैंने बहुत कुछ सीखा है, और अब मैं बड़ी ज़िम्मेदारियाँ लेना चाहता हूँ।"),
    H(T("3. 'What is your expected salary?'", "3. 'What is your expected salary?'")),
    P(T("Pehle **range** batao ya poochho ki company ki range kya hai. Number ke saath **'depending on the role and responsibilities'** jodo.",
        "Give a **range**, or ask what the company's range is. Add **'depending on the role and responsibilities'** to the number.")),
    EX("I am looking for something in the range of X to Y, depending on the role. | मैं role के हिसाब से X से Y के बीच की उम्मीद रखता हूँ।",
       "What is the budget range for this position? | इस पद के लिए बजट की सीमा क्या है?"),
    H(T("4. 'When can you join?' (notice period)", "4. 'When can you join?' (notice period)")),
    EX("My notice period is 30 days, and I can discuss an earlier date if needed. | मेरा notice period 30 दिन है, और ज़रूरत हो तो जल्दी की तारीख पर बात कर सकता हूँ।"),
    H(T("5. 'Do you have any questions for us?'", "5. 'Do you have any questions for us?'")),
    P(T("Kabhi bhi 'No' mat bolo. Kam se kam **ek** sawaal poochho.", "Never just say 'No'. Ask at least **one** question.")),
    EX("What does a typical day look like for this role? | इस role के लिए एक आम दिन कैसा होता है?",
       "What are the next steps in the process? | आगे की process के steps क्या हैं?",
       "What would success look like in the first three months? | पहले तीन महीनों में सफलता कैसी दिखेगी?"),
    TIP(T("Jawab mein **'I'** bolo, 'we' nahi — interviewer aapka role jaanna chahta hai.", "Say **'I'** in your answers, not 'we' — the interviewer wants to know your role.")),
], [
    Q(T("Purane company ke baare mein?", "About your old company?"), ["Say it was terrible.", "Focus on what you learned and want next.", "Complain about the manager.", "Say nothing and hang up."], 1, T("Burai mat karo; seekhne par baat karo.", "Do not criticise; talk about learning.")),
    Q(T("Salary ke sawaal par sabse safe?", "Safest answer on salary?"), ["Give a range, depending on the role.", "Refuse to answer.", "Give a huge number.", "Say 'Any'."], 0, T("Range + 'depending on the role'.", "A range + 'depending on the role'.")),
    Q(T("Interviewer poochhe 'Any questions?'", "The interviewer asks 'Any questions?'"), ["No.", "Ask a question about the role or next steps.", "Ask about leave on day one.", "Ask nothing and laugh."], 1, T("Hamesha kam se kam ek sawaal.", "Always at least one question.")),
    Q(T("Notice period kaise batate hain?", "How do you state your notice period?"), ["My notice period is 30 days.", "I have thirty days notice period only.", "Notice is thirty.", "Days thirty."], 0, T("Seedha, saaf sentence.", "A plain, clear sentence.")),
    Q(T("'Tell me about yourself' kitne second?", "How long for 'Tell me about yourself'?"), ["5 seconds", "About 45 seconds", "5 minutes", "Do not answer"], 1, T("Present, past, future — lagbhag 45 second.", "Present, past, future — about 45 seconds.")),
])

LESSON("c04", "s7", "When something goes wrong: audio, lag, nerves", T("Jab kuch gadbad ho: awaaz, lag, ghabrahat", "When something goes wrong: audio, lag and nerves"), [
    P(T("Call mein dikkat aana normal hai. Interviewer ye dekhte hain ki aap **dikkat ko kaise sambhalte** ho — ye ek achha impression ban sakta hai.",
        "Problems on calls are normal. Interviewers watch **how you handle** them — it can leave a good impression.")),
    H(T("Awaaz ya internet ki dikkat", "Audio or internet problems")),
    TBL([T("Dikkat", "Problem"), T("Kya bolein", "What to say")],
        [T("Aapko unki awaaz nahi aa rahi", "You cannot hear them"), "I am afraid I cannot hear you clearly. Could you please check your microphone?"],
        [T("Unhe aapki awaaz nahi aa rahi", "They cannot hear you"), "I think there may be a problem with my audio. Let me reconnect."],
        [T("Awaaz toot rahi hai", "The audio is breaking up"), "You are breaking up a little. Could you repeat the last part?"],
        [T("Call kat gayi", "The call dropped"), "Sorry about that, my connection dropped. Where were we?"],
        [T("Phone par fallback", "Phone fallback"), "Would it be okay if I call you back on my phone?"]),
    H(T("Jawab na aaye to", "When you do not know the answer")),
    P(T("Kabhi jhooth ya andaaza mat do. Sach bolo aur **seekhne ki taiyari** dikhao.", "Never lie or guess wildly. Be honest and show **willingness to learn**.")),
    EX("I have not worked with that directly, but I understand the basic idea. | मैंने उस पर सीधे काम नहीं किया, पर मैं बुनियादी विचार समझता हूँ।",
       "I would need to look into that, but here is how I would approach it. | मुझे उसे देखना पड़ेगा, पर मैं इस तरह उसे करूँगा।",
       "I am not sure, but I can find out and get back to you. | मुझे पक्का नहीं पता, पर मैं पता करके आपको बता सकता हूँ।"),
    H(T("Ghabrahat ko sambhalna", "Handling nerves")),
    P(T("Jawab se pehle **ek lambi saans** lo. Dheere bolo. Agar galti ho jaye to bas bolo: 'Let me rephrase that.' aur aage badho. Koi bhi perfect nahi bolta.",
        "Take **one deep breath** before answering. Speak slowly. If you slip, just say 'Let me rephrase that.' and carry on. Nobody speaks perfectly.")),
    EX("Let me rephrase that. | मुझे इसे दूसरे तरीके से कहने दीजिए।", "Sorry, I lost my train of thought for a second. | माफ़ कीजिए, एक पल के लिए मैं बात भूल गया।"),
], [
    Q(T("Unki awaaz nahi aa rahi to?", "If you cannot hear them?"), ["Say 'I am afraid I cannot hear you clearly.'", "Hang up immediately.", "Shout.", "Wait silently for 10 minutes."], 0, T("Polite aur seedha.", "Polite and direct.")),
    Q(T("Call kat jaye to?", "If the call drops?"), ["Do not call back.", "Call back and say 'Sorry, my connection dropped.'", "Blame the interviewer.", "Send an angry email."], 1, T("Turant wapas judo aur maafi maango.", "Reconnect quickly and apologise.")),
    Q(T("Jawab nahi pata to?", "If you do not know the answer?"), ["Invent something.", "Be honest and show how you would find out.", "Say 'Not my problem.'", "Say 'This question is bad.'"], 1, T("Sach + seekhne ki taiyari.", "Honesty + willingness to learn.")),
    Q(T("Galti ho jaye to?", "If you make a slip?"), ["Say 'Let me rephrase that.' and continue.", "Apologise for two minutes.", "Stop talking.", "Laugh and hang up."], 0, T("Chhota correction, aage badho.", "A short correction, then move on.")),
    Q(T("Ghabrahat mein sabse pehle?", "First thing when nervous?"), ["Speak faster.", "Take a slow breath and speak slowly.", "Drink coffee quickly.", "Skip the question."], 1, T("Saans + dheere bolna.", "Breath + slow speech.")),
])

LESSON("c05", "s7", "Closing the call and following up", T("Call khatam karna aur follow-up", "Closing the call and following up"), [
    P(T("Call ka **ant** bhi utna hi zaroori hai jitna shuruaat. Aakhri 30 second mein aap interest dikhate ho aur agle step ke baare mein pooch lete ho.",
        "The **end** of the call matters as much as the start. In the last 30 seconds you show interest and ask about the next step.")),
    H(T("Call band karne ka formula", "The closing formula")),
    P(T("**Dhanyavaad → interest → agla step**", "**Thanks → interest → next step**")),
    EX("Thank you for your time today. | आज अपना समय देने के लिए धन्यवाद।",
       "I am very interested in this role. | मुझे इस role में बहुत रुचि है।",
       "Could you tell me what the next steps are? | क्या आप बता सकते हैं कि आगे के steps क्या हैं?",
       "I look forward to hearing from you. | मैं आपके जवाब का इंतज़ार करूँगा।",
       "Have a great day! | आपका दिन शुभ हो!"),
    H(T("Thank-you email (call ke baad, 24 ghante ke andar)", "Thank-you email (within 24 hours after the call)")),
    EX("Subject: Thank you, Java Developer interview | विषय: धन्यवाद, Java Developer interview",
       "Hi Ms. Mehta, thank you for speaking with me today. | नमस्ते मेहता जी, आज मुझसे बात करने के लिए धन्यवाद।",
       "I enjoyed learning about the team and the project. | टीम और project के बारे में जानकर अच्छा लगा।",
       "Please let me know if you need anything else from my side. | मेरी तरफ से कुछ और चाहिए तो बताइएगा।",
       "Best regards, Rahul | सादर, राहुल"),
    TIP(T("Email chhota rakho — 4 se 5 line. Ek specific baat jodo jo call mein hui thi, isse aap yaad rehte ho.", "Keep the email short — 4 to 5 lines. Mention one specific thing from the call so they remember you.")),
    H(T("Agar jawab na aaye", "If you do not hear back")),
    EX("I wanted to follow up on my interview from last week. | मैं पिछले हफ़्ते के अपने interview पर follow-up करना चाहता था।",
       "Could you share an update on the timeline? | क्या आप समय-सीमा पर कोई update दे सकते हैं?"),
    P(T("Pehla follow-up **5–7 din baad** karo, ek hi baar ya do baar. Zyada baar nahi.", "Send the first follow-up **5–7 days later**, once or twice at most.")),
], [
    Q(T("Call band karne ka formula?", "The closing formula?"), ["Thanks, interest, next step", "Bye, bye, bye", "Complain, apologise, hang up", "Silence"], 0, T("Dhanyavaad, interest, agla step.", "Thanks, interest, next step.")),
    Q(T("Thank-you email kab bhejein?", "When do you send the thank-you email?"), ["After a month", "Within 24 hours", "Never", "Before the call"], 1, T("24 ghante ke andar.", "Within 24 hours.")),
    Q(T("Follow-up kab?", "When to follow up?"), ["After 5–7 days", "Every hour", "The same minute", "After one year"], 0, T("Thoda ruk kar, polite tareeke se.", "Wait a little, politely.")),
    Q(T("Aakhri sawaal ke liye accha phrase?", "A good closing question?"), ["What are the next steps?", "Will you hire me or not?", "Bye.", "Is this job easy?"], 0, T("Agle step ke baare mein poochna professional hai.", "Asking about next steps is professional.")),
    Q(T("Email kitna lamba?", "How long should the email be?"), ["4–5 lines", "5 pages", "One word", "A poem"], 0, T("Chhota aur specific.", "Short and specific.")),
])
